# Motion setup — ultra-modern-lovable-style

```bash
npm i gsap @studio-freight/lenis
```

## Lenis initialization (Next.js app/providers.tsx)
```tsx
'use client'
import { useEffect } from 'react'
import Lenis from '@studio-freight/lenis'

export function LenisProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    const lenis = new Lenis({ lerp: 0.1, smoothWheel: true, syncTouch: true })
    function raf(time: number) { lenis.raf(time); requestAnimationFrame(raf) }
    requestAnimationFrame(raf)
    return () => lenis.destroy()
  }, [])
  return <>{children}</>
}
```

## GSAP + ScrollTrigger (with prefers-reduced-motion)
```tsx
import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
gsap.registerPlugin(ScrollTrigger)

const mm = gsap.matchMedia()
mm.add({
  reduceMotion: '(prefers-reduced-motion: reduce)',
  hasMotion: '(prefers-reduced-motion: no-preference)'
}, (ctx) => {
  const { reduceMotion } = ctx.conditions!
  if (reduceMotion) {
    // Instant fades only
    gsap.set('.fade-up', { opacity: 1, y: 0 })
  } else {
    gsap.from('.fade-up', {
      y: 40, opacity: 0, duration: 0.7, ease: 'power4.out',
      scrollTrigger: { trigger: '.fade-up', start: 'top 80%' }
    })
  }
})
```
